  1→/**
  2→ * Shared type definitions for the thos dashboard.
  3→ *
  4→ * Three categories:
  5→ * 1. **Claude NDJSON protocol** — messages the Claude CLI sends over its
  6→ *    `--sdk-url` WebSocket connection (CLI → WS server).
  7→ * 2. **Browser ↔ Server** — messages exchanged between the React client
  8→ *    and the standalone WS relay server.
  9→ * 3. **UI state** — view-model types consumed by React components.
 10→ */
 11→
 12→// ── Claude NDJSON protocol messages (CLI → server) ────────────────────────
 13→
 14→/**
 15→ * Sent once after the first user prompt is received. Contains session
 16→ * metadata like the model name, working directory, and available tools.
 17→ */
 18→export interface ClaudeSystemInit {
 19→  type: "system";
 20→  subtype: "init";
 21→  session_id: string;
 22→  tools: unknown[];
 23→  mcp_servers: unknown[];
 24→  model: string;
 25→  cwd: string;
 26→}
 27→
 28→/**
 29→ * An assistant turn. `message.content` is an array of content blocks
 30→ * (text, tool_use, tool_result) that may arrive incrementally — each
 31→ * NDJSON line is a complete snapshot of the message so far.
 32→ */
 33→export interface ClaudeAssistant {
 34→  type: "assistant";
 35→  message: {
 36→    id: string;
 37→    role: "assistant";
 38→    content: AssistantContentBlock[];
 39→    model: string;
 40→    stop_reason: string | null;
 41→  };
 42→  session_id: string;
 43→}
 44→
 45→/** A single content block inside an assistant message. */
 46→export type AssistantContentBlock =
 47→  | { type: "text"; text: string }
 48→  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
 49→  | { type: "tool_result"; tool_use_id: string; content: string };
 50→
 51→/**
 52→ * Terminal message for a session. Includes cost/duration metrics.
 53→ * `is_error` is true when `subtype` is `"error"`.
 54→ */
 55→export interface ClaudeResult {
 56→  type: "result";
 57→  subtype: "success" | "error";
 58→  result?: string;
 59→  error?: string;
 60→  session_id: string;
 61→  cost_usd: number;
 62→  duration_ms: number;
 63→  duration_api_ms: number;
 64→  is_error: boolean;
 65→  num_turns: number;
 66→}
 67→
 68→/**
 69→ * Claude is requesting permission to execute a tool. The dashboard must
 70→ * reply with a `control_response` (allow / deny) before the CLI proceeds.
 71→ *
 72→ * Wire format uses a nested `request` object with `request_id` at the
 73→ * top level for correlation (matches Companion protocol docs).
 74→ */
 75→export interface ClaudeControlRequest {
 76→  type: "control_request";
 77→  request_id: string;
 78→  request: {
 79→    subtype: "can_use_tool";
 80→    tool_name: string;
 81→    input: Record<string, unknown>;
 82→    tool_use_id?: string;
 83→    description?: string;
 84→  };
 85→  session_id?: string;
 86→}
 87→
 88→/**
 89→ * Hook lifecycle events emitted during CLI startup. `hook_response` is
 90→ * the signal that the CLI is ready to receive the first user prompt.
 91→ */
 92→export interface ClaudeSystemHook {
 93→  type: "system";
 94→  subtype: "hook_started" | "hook_response";
 95→  session_id?: string;
 96→}
 97→
 98→/** Discriminated union of all known Claude NDJSON message shapes. */
 99→export type ClaudeMessage =
100→  | ClaudeSystemInit
101→  | ClaudeAssistant
102→  | ClaudeResult
103→  | ClaudeControlRequest
104→  | ClaudeSystemHook
105→  | { type: string; subtype?: string; [key: string]: unknown };
106→
107→// ── Browser ↔ Server messages ─────────────────────────────────────────────
108→
109→/** Browser asks the server to spawn a new Claude CLI process. */
110→export interface BrowserSpawn {
111→  type: "spawn";
112→  prompt: string;
113→}
114→
115→/** Browser sends a follow-up message to an already-running Claude session. */
116→export interface BrowserSendMessage {
117→  type: "send_message";
118→  agentId: string;
119→  content: string;
120→}
121→
122→/** Browser responds to a tool approval request (allow or deny). */
123→export interface BrowserControlResponse {
124→  type: "control_response";
125→  agentId: string;
126→  request_id: string;
127→  allow: boolean;
128→}
129→
130→/** Union of all messages the browser can send to the WS server. */
131→export type BrowserMessage = BrowserSpawn | BrowserSendMessage | BrowserControlResponse;
132→
133→/** Server relays a raw Claude NDJSON message to the browser. */
134→export interface ServerRelay {
135→  type: "relay";
136→  agentId: string;
137→  message: ClaudeMessage;
138→}
139→
140→/** Server notifies the browser of an agent status change. */
141→export interface ServerStatus {
142→  type: "status";
143→  agentId: string;
144→  status: AgentStatus;
145→}
146→
147→/** Server reports an error (e.g. no active session, process crash). */
148→export interface ServerError {
149→  type: "error";
150→  agentId: string;
151→  error: string;
152→}
153→
154→/** Summary of an agent for the sidebar. */
155→export interface AgentInfo {
156→  agentId: string;
157→  status: AgentStatus;
158→  tmuxSession: string | null;
159→  label: string;
160→  createdAt: number;
161→}
162→
163→/** Server sends the full list of agents after every state change. */
164→export interface ServerAgentList {
165→  type: "agent_list";
166→  agents: AgentInfo[];
167→}
168→
169→/** Server confirms a new agent was spawned and assigns its ID. */
170→export interface ServerSpawned {
171→  type: "spawned";
172→  agentId: string;
173→}
174→
175→/** Server replays full message history for an agent on browser connect. */
176→export interface ServerMessageHistory {
177→  type: "message_history";
178→  agentId: string;
179→  messages: ServerMessage[];
180→}
181→
182→/** CLI WebSocket disconnected (process may have crashed or exited). */
183→export interface ServerCliDisconnected {
184→  type: "cli_disconnected";
185→  agentId: string;
186→}
187→
188→/** CLI WebSocket reconnected (e.g. after relaunch with --resume). */
189→export interface ServerCliConnected {
190→  type: "cli_connected";
191→  agentId: string;
192→}
193→
194→/** Union of all messages the WS server can send to the browser. */
195→export type ServerMessage =
196→  | ServerRelay
197→  | ServerStatus
198→  | ServerError
199→  | ServerAgentList
200→  | ServerSpawned
201→  | ServerMessageHistory
202→  | ServerCliDisconnected
203→  | ServerCliConnected;
204→
205→// ── UI state ──────────────────────────────────────────────────────────────
206→
207→/**
208→ * Lifecycle states of the Claude agent process:
209→ * - `idle`      — no process running, ready to spawn
210→ * - `spawning`  — process launched, waiting for CLI to connect via WS
211→ * - `connected` — CLI connected and `system/init` received
212→ * - `thinking`  — waiting for assistant response
213→ * - `done`      — `result` message received, process finished
214→ * - `error`     — process crashed or unexpected failure
215→ */
216→export type AgentStatus = "idle" | "spawning" | "connected" | "thinking" | "done" | "disconnected" | "error";
217→
218→export type ChatMessageRole = "user" | "assistant" | "system";
219→
220→/**
221→ * A single entry in the chat message list. System messages include
222→ * session init info and result summaries. Messages with a `controlRequest`
223→ * are rendered as tool-approval cards instead of plain bubbles.
224→ */
225→export interface ChatMessage {
226→  id: string;
227→  role: ChatMessageRole;
228→  content: string;
229→  timestamp: number;
230→  /** Present when this message represents a tool approval request. */
231→  controlRequest?: {
232→    id: string;
233→    tool_name: string;
234→    input: Record<string, unknown>;
235→    /** Set to true after the user allows or denies. */
236→    resolved?: boolean;
237→  };
238→}
239→

  1→"use client";
  2→
  3→/**
  4→ * Main chat interface for the thos dashboard.
  5→ *
  6→ * Composes {@link StatusBar}, a scrollable message list ({@link Message}
  7→ * and {@link ControlRequest} cards), and an input bar. The submit button
  8→ * text toggles between "Spawn" (when idle/done) and "Send" (when an
  9→ * agent session is active). Auto-scrolls on new messages.
 10→ *
 11→ * Receives all data and callbacks via props — the parent page component
 12→ * owns the WebSocket hook and orchestrates multiple agents.
 13→ */
 14→
 15→import { useEffect, useRef, useState } from "react";
 16→import type { AgentStatus, ChatMessage } from "@/lib/types";
 17→import { StatusBar } from "./status-bar";
 18→import { Message } from "./message";
 19→import { ControlRequest } from "./control-request";
 20→import { Button } from "@/components/ui/button";
 21→
 22→export function Chat({
 23→  connected,
 24→  status,
 25→  messages,
 26→  onSendMessage,
 27→  onSpawnAgent,
 28→  onRespondToControl,
 29→}: {
 30→  connected: boolean;
 31→  status: AgentStatus;
 32→  messages: ChatMessage[];
 33→  onSendMessage: (content: string) => void;
 34→  onSpawnAgent: (prompt: string) => void;
 35→  onRespondToControl: (requestId: string, allow: boolean) => void;
 36→}) {
 37→  const [input, setInput] = useState("");
 38→  const scrollRef = useRef<HTMLDivElement>(null);
 39→
 40→  useEffect(() => {
 41→    scrollRef.current?.scrollTo({
 42→      top: scrollRef.current.scrollHeight,
 43→      behavior: "smooth",
 44→    });
 45→  }, [messages]);
 46→
 47→  const isActive = status === "connected" || status === "thinking";
 48→
 49→  function handleSubmit(e: React.FormEvent) {
 50→    e.preventDefault();
 51→    const trimmed = input.trim();
 52→    if (!trimmed) return;
 53→
 54→    if (isActive) {
 55→      onSendMessage(trimmed);
 56→    } else {
 57→      onSpawnAgent(trimmed);
 58→    }
 59→    setInput("");
 60→  }
 61→
 62→  return (
 63→    <div className="flex h-full flex-col">
 64→      <StatusBar connected={connected} status={status} />
 65→
 66→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-2">
 67→        {messages.length === 0 && (
 68→          <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
 69→            Type a prompt to spawn a Claude agent
 70→          </div>
 71→        )}
 72→        {messages.map((msg) =>
 73→          msg.controlRequest ? (
 74→            <ControlRequest
 75→              key={msg.id}
 76→              message={msg}
 77→              onRespond={onRespondToControl}
 78→            />
 79→          ) : (
 80→            <Message key={msg.id} message={msg} />
 81→          )
 82→        )}
 83→      </div>
 84→
 85→      <form
 86→        onSubmit={handleSubmit}
 87→        className="flex gap-2 border-t px-4 py-3"
 88→      >
 89→        <input
 90→          type="text"
 91→          value={input}
 92→          onChange={(e) => setInput(e.target.value)}
 93→          placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
 94→          className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
 95→        />
 96→        <Button type="submit" disabled={!connected || !input.trim()}>
 97→          {isActive ? "Send" : "Spawn"}
 98→        </Button>
 99→      </form>
100→    </div>
101→  );
102→}
103→

  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * Resilience features:
 11→ * - Handles `message_history` replay from server on connect/reconnect.
 12→ * - Handles `cli_disconnected` / `cli_connected` events.
 13→ * - Deduplicates messages using a per-agent Set of seen message IDs.
 14→ * - Robust reconnection guard (clears previous timer before scheduling).
 15→ */
 16→
 17→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 18→import type {
 19→  AgentInfo,
 20→  AgentStatus,
 21→  ChatMessage,
 22→  ClaudeAssistant,
 23→  ClaudeControlRequest,
 24→  ClaudeResult,
 25→  ClaudeSystemInit,
 26→  ServerMessage,
 27→  ServerMessageHistory,
 28→} from "@/lib/types";
 29→
 30→const WS_URL = "ws://localhost:9900/browser";
 31→
 32→/** Per-agent client state. */
 33→export interface AgentClientState {
 34→  status: AgentStatus;
 35→  messages: ChatMessage[];
 36→  label: string;
 37→  tmuxSession: string | null;
 38→  createdAt: number;
 39→}
 40→
 41→/**
 42→ * Extract displayable text from a Claude assistant message.
 43→ * Content blocks may be text, tool_use, or tool_result — each is
 44→ * handled defensively since the array structure can vary.
 45→ */
 46→function extractText(msg: ClaudeAssistant): string {
 47→  const blocks = msg.message?.content;
 48→  if (!blocks || !Array.isArray(blocks)) return "";
 49→  return blocks
 50→    .map((b) => {
 51→      if (b.type === "text") return b.text;
 52→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 53→      if (b.type === "tool_result") return `[tool_result: ${b.content}]`;
 54→      return "";
 55→    })
 56→    .filter(Boolean)
 57→    .join("\n");
 58→}
 59→
 60→/** Module-level counter for generating unique message IDs. */
 61→let msgCounter = 0;
 62→function nextId() {
 63→  return `msg-${Date.now()}-${++msgCounter}`;
 64→}
 65→
 66→/**
 67→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
 68→ * Used both for live messages and for replaying message_history.
 69→ */
 70→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
 71→  if (relayMsg.type === "relay") {
 72→    const msg = relayMsg.message;
 73→
 74→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
 75→      const init = msg as ClaudeSystemInit;
 76→      return {
 77→        id: nextId(),
 78→        role: "system",
 79→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
 80→        timestamp: Date.now(),
 81→      };
 82→    }
 83→
 84→    if (msg.type === "assistant") {
 85→      const text = extractText(msg as ClaudeAssistant);
 86→      if (text) {
 87→        return {
 88→          id: nextId(),
 89→          role: "assistant",
 90→          content: text,
 91→          timestamp: Date.now(),
 92→        };
 93→      }
 94→      return null;
 95→    }
 96→
 97→    if (msg.type === "result") {
 98→      const result = msg as ClaudeResult;
 99→      const summary = result.is_error
100→        ? `Error: ${result.error}`
101→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
102→      return {
103→        id: nextId(),
104→        role: "system",
105→        content: summary,
106→        timestamp: Date.now(),
107→      };
108→    }
109→
110→    if (msg.type === "control_request") {
111→      const cr = msg as ClaudeControlRequest;
112→      return {
113→        id: nextId(),
114→        role: "system",
115→        content: `Tool approval requested: ${cr.request.tool_name}`,
116→        timestamp: Date.now(),
117→        controlRequest: {
118→          id: cr.request_id,
119→          tool_name: cr.request.tool_name,
120→          input: cr.request.input,
121→        },
122→      };
123→    }
124→  }
125→
126→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
127→    return {
128→      id: nextId(),
129→      role: "system",
130→      content: `Error: ${relayMsg.error}`,
131→      timestamp: Date.now(),
132→    };
133→  }
134→
135→  return null;
136→}
137→
138→export function useWebSocket() {
139→  const wsRef = useRef<WebSocket | null>(null);
140→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
141→  const [connected, setConnected] = useState(false);
142→
143→  // Multi-agent state
144→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
145→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
146→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
147→
148→  // Per-agent deduplication: track count of processed messages per agent
149→  // to avoid duplicating messages already in local state during history replay.
150→  const processedCountRef = useRef<Map<string, number>>(new Map());
151→
152→  /** Immutably update a single agent's state in the Map. */
153→  const updateAgent = useCallback(
154→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
155→      setAgents((prev) => {
156→        const existing = prev.get(agentId);
157→        if (!existing) return prev;
158→        const next = new Map(prev);
159→        next.set(agentId, updater(existing));
160→        return next;
161→      });
162→    },
163→    []
164→  );
165→
166→  const connect = useCallback(() => {
167→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
168→    if (wsRef.current) {
169→      wsRef.current.close();
170→      wsRef.current = null;
171→    }
172→
173→    const ws = new WebSocket(WS_URL);
174→    wsRef.current = ws;
175→
176→    ws.onopen = () => setConnected(true);
177→
178→    ws.onclose = () => {
179→      setConnected(false);
180→      wsRef.current = null;
181→      // Reconnection guard: clear any existing timer before scheduling
182→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
183→      reconnectTimer.current = setTimeout(() => connect(), 2000);
184→    };
185→
186→    ws.onerror = () => {
187→      // onclose will fire after onerror, which triggers reconnect
188→    };
189→
190→    ws.onmessage = (event) => {
191→      let data: ServerMessage;
192→      try {
193→        data = JSON.parse(event.data as string);
194→      } catch {
195→        return;
196→      }
197→
198→      // ── message_history: replay full history from server ──
199→      if (data.type === "message_history") {
200→        const historyMsg = data as ServerMessageHistory;
201→        const agentId = historyMsg.agentId;
202→        const serverMessages = historyMsg.messages;
203→
204→        // Convert all server messages to ChatMessages
205→        const chatMessages: ChatMessage[] = [];
206→        for (const sm of serverMessages) {
207→          const cm = relayChatMessage(agentId, sm);
208→          if (cm) chatMessages.push(cm);
209→        }
210→
211→        // Skip messages already processed locally (dedup)
212→        const alreadyProcessed = processedCountRef.current.get(agentId) ?? 0;
213→        const newMessages = chatMessages.slice(alreadyProcessed);
214→
215→        if (newMessages.length > 0) {
216→          setAgents((prev) => {
217→            const existing = prev.get(agentId);
218→            if (!existing) {
219→              // Agent not yet in local state — create it
220→              const next = new Map(prev);
221→              next.set(agentId, {
222→                status: "idle",
223→                messages: chatMessages, // use full history for new agent
224→                label: "",
225→                tmuxSession: null,
226→                createdAt: 0,
227→              });
228→              return next;
229→            }
230→            // Replace messages with full server history (source of truth)
231→            const next = new Map(prev);
232→            next.set(agentId, { ...existing, messages: chatMessages });
233→            return next;
234→          });
235→        }
236→
237→        processedCountRef.current.set(agentId, chatMessages.length);
238→        return;
239→      }
240→
241→      // ── cli_disconnected: show system message ──
242→      if (data.type === "cli_disconnected") {
243→        updateAgent(data.agentId, (prev) => ({
244→          ...prev,
245→          status: "disconnected",
246→          messages: [
247→            ...prev.messages,
248→            {
249→              id: nextId(),
250→              role: "system",
251→              content: "CLI disconnected — attempting reconnect...",
252→              timestamp: Date.now(),
253→            },
254→          ],
255→        }));
256→        return;
257→      }
258→
259→      // ── cli_connected: show system message ──
260→      if (data.type === "cli_connected") {
261→        updateAgent(data.agentId, (prev) => ({
262→          ...prev,
263→          messages: [
264→            ...prev.messages,
265→            {
266→              id: nextId(),
267→              role: "system",
268→              content: "CLI reconnected",
269→              timestamp: Date.now(),
270→            },
271→          ],
272→        }));
273→        return;
274→      }
275→
276→      // ── agent_list: reconcile sidebar state from server ──
277→      if (data.type === "agent_list") {
278→        const serverAgents = data.agents as AgentInfo[];
279→        setAgents((prev) => {
280→          const next = new Map(prev);
281→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
282→
283→          // Update or add agents from server
284→          for (const info of serverAgents) {
285→            const existing = next.get(info.agentId);
286→            if (existing) {
287→              next.set(info.agentId, {
288→                ...existing,
289→                status: info.status,
290→                tmuxSession: info.tmuxSession,
291→                label: info.label,
292→              });
293→            } else {
294→              next.set(info.agentId, {
295→                status: info.status,
296→                messages: [],
297→                label: info.label,
298→                tmuxSession: info.tmuxSession,
299→                createdAt: info.createdAt,
300→              });
301→            }
302→          }
303→
304→          // Remove agents no longer on the server
305→          for (const id of next.keys()) {
306→            if (!serverIds.has(id)) {
307→              next.delete(id);
308→            }
309→          }
310→
311→          return next;
312→        });
313→        setAgentOrder(serverAgents.map((a) => a.agentId));
314→        return;
315→      }
316→
317→      // ── spawned: auto-select the newly created agent ──
318→      if (data.type === "spawned") {
319→        setActiveAgentId(data.agentId);
320→        return;
321→      }
322→
323→      // ── status: update a specific agent's status ──
324→      if (data.type === "status") {
325→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
326→        return;
327→      }
328→
329→      // ── error: append to agent's message list ──
330→      if (data.type === "error") {
331→        updateAgent(data.agentId, (prev) => ({
332→          ...prev,
333→          messages: [
334→            ...prev.messages,
335→            {
336→              id: nextId(),
337→              role: "system",
338→              content: `Error: ${data.error}`,
339→              timestamp: Date.now(),
340→            },
341→          ],
342→        }));
343→        // Track processed count for dedup
344→        processedCountRef.current.set(
345→          data.agentId,
346→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
347→        );
348→        return;
349→      }
350→
351→      // ── relay: append claude message to agent's history ──
352→      if (data.type === "relay") {
353→        const agentId = data.agentId;
354→        const chatMsg = relayChatMessage(agentId, data);
355→
356→        if (chatMsg) {
357→          updateAgent(agentId, (prev) => ({
358→            ...prev,
359→            messages: [...prev.messages, chatMsg],
360→          }));
361→          // Track processed count for dedup
362→          processedCountRef.current.set(
363→            agentId,
364→            (processedCountRef.current.get(agentId) ?? 0) + 1
365→          );
366→        }
367→        return;
368→      }
369→    };
370→  }, [updateAgent]);
371→
372→  useEffect(() => {
373→    connect();
374→    return () => {
375→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
376→      wsRef.current?.close();
377→    };
378→  }, [connect]);
379→
380→  const send = useCallback((data: object) => {
381→    if (wsRef.current?.readyState === WebSocket.OPEN) {
382→      wsRef.current.send(JSON.stringify(data));
383→    }
384→  }, []);
385→
386→  const spawnAgent = useCallback(
387→    (prompt: string) => {
388→      send({ type: "spawn", prompt });
389→    },
390→    [send]
391→  );
392→
393→  const sendMessage = useCallback(
394→    (content: string) => {
395→      if (!activeAgentId) return;
396→      // Optimistically add user message to local state
397→      updateAgent(activeAgentId, (prev) => ({
398→        ...prev,
399→        messages: [
400→          ...prev.messages,
401→          {
402→            id: nextId(),
403→            role: "user",
404→            content,
405→            timestamp: Date.now(),
406→          },
407→        ],
408→      }));
409→      send({ type: "send_message", agentId: activeAgentId, content });
410→    },
411→    [send, activeAgentId, updateAgent]
412→  );
413→
414→  const respondToControl = useCallback(
415→    (requestId: string, allow: boolean) => {
416→      if (!activeAgentId) return;
417→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
418→      updateAgent(activeAgentId, (prev) => ({
419→        ...prev,
420→        messages: prev.messages.map((m) =>
421→          m.controlRequest?.id === requestId
422→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
423→            : m
424→        ),
425→      }));
426→    },
427→    [send, activeAgentId, updateAgent]
428→  );
429→
430→  // Derived values for the active agent
431→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
432→  const activeStatus = useMemo<AgentStatus>(
433→    () => activeAgent?.status ?? "idle",
434→    [activeAgent?.status]
435→  );
436→  const activeMessages = useMemo<ChatMessage[]>(
437→    () => activeAgent?.messages ?? [],
438→    [activeAgent?.messages]
439→  );
440→
441→  return {
442→    connected,
443→    agents,
444→    agentOrder,
445→    activeAgentId,
446→    setActiveAgentId,
447→    activeStatus,
448→    activeMessages,
449→    spawnAgent,
450→    sendMessage,
451→    respondToControl,
452→  };
453→}
454→

  1→/**
  2→ * Standalone WebSocket relay server for the thos dashboard.
  3→ *
  4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
  5→ * `dev` script). It cannot be a Next.js API route because API routes don't
  6→ * support persistent WebSocket connections.
  7→ *
  8→ * ## Architecture
  9→ *
 10→ * Two WebSocket path families:
 11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
 12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
 13→ *
 14→ * The server supports multiple concurrent agents, each tracked in the
 15→ * `agents` Map keyed by a short random ID.
 16→ *
 17→ * ## Resilience features
 18→ *
 19→ * - **Server-side message history** — every relay message is stored per-agent.
 20→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
 21→ * - **Multi-browser** — multiple tabs can connect simultaneously.
 22→ * - **CLI relaunch** — dead agents with a sessionId are relaunched with `--resume`.
 23→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
 24→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
 25→ *
 26→ * ## Message flow
 27→ *
 28→ * 1. Browser sends `{ type: "spawn", prompt }`.
 29→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
 30→ * 3. CLI connects on `/claude/<agentId>`, sends `system/hook_started` then `system/hook_response`.
 31→ * 4. On `hook_response`, server forwards the pending prompt to the CLI.
 32→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
 33→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
 34→ * 7. `control_request` messages (tool approval) are relayed to the browser;
 35→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
 36→ */
 37→import { WebSocketServer, WebSocket } from "ws";
 38→import { execSync, spawn } from "child_process";
 39→import { randomBytes } from "crypto";
 40→import type { IncomingMessage } from "http";
 41→import type {
 42→  BrowserMessage,
 43→  ClaudeMessage,
 44→  ServerMessage,
 45→  AgentStatus,
 46→  AgentInfo,
 47→} from "../lib/types";
 48→import { SessionStore, type PersistedAgent } from "./session-store";
 49→
 50→const PORT = 9900;
 51→const TMUX_SESSION_PREFIX = "thos-agent";
 52→const wss = new WebSocketServer({ port: PORT });
 53→const store = new SessionStore();
 54→
 55→// ── Multi-agent state ──────────────────────────────────────────────────────
 56→
 57→interface AgentState {
 58→  agentId: string;
 59→  claudeSocket: WebSocket | null;
 60→  tmuxSession: string | null;
 61→  pendingPrompt: string | null;
 62→  status: AgentStatus;
 63→  label: string;
 64→  createdAt: number;
 65→  /** Captured from system/init, used in subsequent user messages and --resume. */
 66→  sessionId: string | null;
 67→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
 68→  pendingControlRequests: Map<string, Record<string, unknown>>;
 69→  /** All messages sent to the browser for this agent (source of truth). */
 70→  messageHistory: ServerMessage[];
 71→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
 72→  pendingMessages: string[];
 73→}
 74→
 75→const agents = new Map<string, AgentState>();
 76→
 77→/** All active browser connections (supports multiple tabs). */
 78→const browserSockets = new Set<WebSocket>();
 79→
 80→/** Generate a short random agent ID. */
 81→function newAgentId(): string {
 82→  return randomBytes(4).toString("hex");
 83→}
 84→
 85→// ── Persistence helpers ────────────────────────────────────────────────────
 86→
 87→/** Build a PersistedAgent snapshot from live state. */
 88→function toPersistedAgent(agent: AgentState): PersistedAgent {
 89→  return {
 90→    id: agent.agentId,
 91→    state: {
 92→      agentId: agent.agentId,
 93→      status: agent.status,
 94→      tmuxSession: agent.tmuxSession,
 95→      label: agent.label,
 96→      createdAt: agent.createdAt,
 97→      sessionId: agent.sessionId,
 98→    },
 99→    messageHistory: agent.messageHistory,
100→  };
101→}
102→
103→/** Persist agent state (debounced — use for streaming events). */
104→function persistAgent(agent: AgentState) {
105→  store.save(toPersistedAgent(agent));
106→}
107→
108→/** Persist agent state immediately (use for critical state changes). */
109→function persistAgentSync(agent: AgentState) {
110→  store.saveSync(toPersistedAgent(agent));
111→}
112→
113→// ── Restore from disk on startup ───────────────────────────────────────────
114→
115→function restoreAgents() {
116→  const persisted = store.loadAll();
117→  for (const p of persisted) {
118→    const agent: AgentState = {
119→      agentId: p.state.agentId,
120→      claudeSocket: null,
121→      tmuxSession: p.state.tmuxSession,
122→      pendingPrompt: null,
123→      status: p.state.status,
124→      label: p.state.label,
125→      createdAt: p.state.createdAt,
126→      sessionId: p.state.sessionId,
127→      pendingControlRequests: new Map(),
128→      messageHistory: p.messageHistory,
129→      pendingMessages: [],
130→    };
131→
132→    // Agents that weren't "done" or "error" when the server died are now disconnected
133→    if (agent.status !== "done" && agent.status !== "error") {
134→      agent.status = "disconnected";
135→    }
136→
137→    agents.set(agent.agentId, agent);
138→    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${agent.messageHistory.length} messages)`);
139→  }
140→  console.log(`[restore] loaded ${persisted.length} agents from disk`);
141→}
142→
143→restoreAgents();
144→
145→// ── Helpers ────────────────────────────────────────────────────────────────
146→
147→/** Send a JSON message to all connected browsers. */
148→function sendToBrowser(msg: ServerMessage) {
149→  const payload = JSON.stringify(msg);
150→  for (const ws of browserSockets) {
151→    if (ws.readyState === WebSocket.OPEN) {
152→      ws.send(payload);
153→    }
154→  }
155→}
156→
157→/** Build a snapshot of all agents for the sidebar. */
158→function buildAgentList(): AgentInfo[] {
159→  return Array.from(agents.values()).map((a) => ({
160→    agentId: a.agentId,
161→    status: a.status,
162→    tmuxSession: a.tmuxSession,
163→    label: a.label,
164→    createdAt: a.createdAt,
165→  }));
166→}
167→
168→/** Send the full agent list to all browsers. */
169→function broadcastAgentList() {
170→  sendToBrowser({ type: "agent_list", agents: buildAgentList() });
171→}
172→
173→/** Update an agent's status, notify browsers, broadcast list, and persist. */
174→function setAgentStatus(agentId: string, status: AgentStatus) {
175→  const agent = agents.get(agentId);
176→  if (!agent) return;
177→  agent.status = status;
178→  sendToBrowser({ type: "status", agentId, status });
179→  broadcastAgentList();
180→  persistAgentSync(agent);
181→}
182→
183→/**
184→ * Record a message in the agent's history and send to all browsers.
185→ * This is used for relay messages so that message history is the source of truth.
186→ */
187→function recordAndSend(agentId: string, msg: ServerMessage) {
188→  const agent = agents.get(agentId);
189→  if (agent) {
190→    agent.messageHistory.push(msg);
191→    persistAgent(agent); // debounced — streaming messages come fast
192→  }
193→  sendToBrowser(msg);
194→}
195→
196→// ── Agent lifecycle ────────────────────────────────────────────────────────
197→
198→/**
199→ * Terminate a specific agent by killing its tmux session.
200→ * Closes the Claude WebSocket and removes the agent from the Map.
201→ */
202→function killAgent(agentId: string) {
203→  const agent = agents.get(agentId);
204→  if (!agent) return;
205→
206→  if (agent.tmuxSession) {
207→    try {
208→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
209→      console.log(`[tmux] killed session ${agent.tmuxSession}`);
210→    } catch {
211→      // Session may already be dead
212→    }
213→  }
214→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
215→    agent.claudeSocket.close();
216→  }
217→  agents.delete(agentId);
218→  store.remove(agentId);
219→  broadcastAgentList();
220→}
221→
222→/**
223→ * Spawn a new Claude CLI process inside a tmux session.
224→ *
225→ * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
226→ * `/claude/<agentId>`, and sends a `spawned` message to the browser.
227→ */
228→function spawnClaude(prompt: string): string {
229→  const agentId = newAgentId();
230→  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
231→  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;
232→
233→  const agent: AgentState = {
234→    agentId,
235→    claudeSocket: null,
236→    tmuxSession: null,
237→    pendingPrompt: prompt,
238→    status: "spawning",
239→    label,
240→    createdAt: Date.now(),
241→    sessionId: null,
242→    pendingControlRequests: new Map(),
243→    messageHistory: [],
244→    pendingMessages: [],
245→  };
246→  agents.set(agentId, agent);
247→
248→  // Notify browsers
249→  sendToBrowser({ type: "spawned", agentId });
250→  broadcastAgentList();
251→  persistAgentSync(agent);
252→
253→  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
254→  // tmux new-session runs detached (-d) so spawn() returns immediately.
255→  const claudeCmd = `unset CLAUDECODE; exec claude --sdk-url ws://localhost:${PORT}/claude/${agentId}`;
256→
257→  const tmux = spawn("tmux", ["new-session", "-d", "-s", sessionName, "bash", "-c", claudeCmd], {
258→    stdio: "ignore",
259→  });
260→
261→  tmux.on("error", (err) => {
262→    console.error("[tmux spawn error]", err);
263→    setAgentStatus(agentId, "error");
264→    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
265→  });
266→
267→  tmux.on("exit", (code) => {
268→    if (code !== 0) {
269→      console.error(`[tmux] new-session exited with code ${code}`);
270→      setAgentStatus(agentId, "error");
271→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
272→      return;
273→    }
274→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
275→    agent.tmuxSession = sessionName;
276→    broadcastAgentList();
277→    persistAgentSync(agent);
278→  });
279→
280→  return agentId;
281→}
282→
283→/**
284→ * Attempt to relaunch a dead agent's CLI with --resume.
285→ * Only works if the agent has a sessionId from a previous system/init.
286→ */
287→function relaunchAgent(agent: AgentState) {
288→  if (!agent.sessionId) {
289→    console.log(`[relaunch] agent ${agent.agentId} has no sessionId, cannot resume`);
290→    return;
291→  }
292→
293→  const sessionName = agent.tmuxSession ?? `${TMUX_SESSION_PREFIX}-${agent.agentId}`;
294→  console.log(`[relaunch] attempting --resume for agent ${agent.agentId} (session=${agent.sessionId})`);
295→
296→  setAgentStatus(agent.agentId, "spawning");
297→
298→  // Kill any lingering tmux session with the same name
299→  try {
300→    execSync(`tmux kill-session -t ${sessionName}`, { stdio: "ignore" });
301→  } catch {
302→    // fine if it doesn't exist
303→  }
304→
305→  const claudeCmd = `unset CLAUDECODE; exec claude --resume --sdk-url ws://localhost:${PORT}/claude/${agent.agentId}`;
306→
307→  const tmux = spawn("tmux", ["new-session", "-d", "-s", sessionName, "bash", "-c", claudeCmd], {
308→    stdio: "ignore",
309→  });
310→
311→  tmux.on("error", (err) => {
312→    console.error(`[relaunch] tmux error for ${agent.agentId}:`, err);
313→    setAgentStatus(agent.agentId, "error");
314→    recordAndSend(agent.agentId, { type: "error", agentId: agent.agentId, error: `relaunch error: ${err.message}` });
315→  });
316→
317→  tmux.on("exit", (code) => {
318→    if (code !== 0) {
319→      console.error(`[relaunch] tmux exited with code ${code} for ${agent.agentId}`);
320→      setAgentStatus(agent.agentId, "error");
321→      recordAndSend(agent.agentId, { type: "error", agentId: agent.agentId, error: `relaunch tmux exited with code ${code}` });
322→      return;
323→    }
324→    agent.tmuxSession = sessionName;
325→    broadcastAgentList();
326→    persistAgentSync(agent);
327→    console.log(`[relaunch] tmux session ${sessionName} created for agent ${agent.agentId}`);
328→  });
329→}
330→
331→// ── Message handlers ───────────────────────────────────────────────────────
332→
333→/**
334→ * Process an incoming NDJSON message from a specific Claude CLI.
335→ *
336→ * Status flow matches the Companion protocol:
337→ * - hook_response → send pending prompt → "thinking"
338→ * - system/init   → "connected" + capture session_id
339→ * - assistant      → "thinking"
340→ * - result         → "connected" (CLI stays alive for multi-turn)
341→ * - CLI disconnect → "disconnected" (handled in connection close handler)
342→ */
343→function handleClaudeMessage(agentId: string, raw: string) {
344→  const agent = agents.get(agentId);
345→  if (!agent) return;
346→
347→  let msg: ClaudeMessage;
348→  try {
349→    msg = JSON.parse(raw);
350→  } catch {
351→    console.error(`[claude:${agentId}] invalid JSON:`, raw);
352→    return;
353→  }
354→
355→  // Silently ignore keep_alive messages
356→  if (msg.type === "keep_alive") return;
357→
358→  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");
359→
360→  // After hook_response, send the pending prompt
361→  if (
362→    msg.type === "system" &&
363→    (msg as { subtype?: string }).subtype === "hook_response" &&
364→    agent.pendingPrompt &&
365→    agent.claudeSocket?.readyState === WebSocket.OPEN
366→  ) {
367→    const userMsg = JSON.stringify({
368→      type: "user",
369→      message: { role: "user", content: agent.pendingPrompt },
370→      parent_tool_use_id: null,
371→      session_id: agent.sessionId ?? "",
372→    });
373→    console.log(`[server → claude:${agentId}]`, userMsg);
374→    agent.claudeSocket.send(userMsg + "\n");
375→    agent.pendingPrompt = null;
376→    setAgentStatus(agentId, "thinking");
377→  }
378→
379→  // Track status based on message type
380→  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
381→    // Capture session_id for subsequent user messages
382→    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
383→    setAgentStatus(agentId, "connected");
384→  } else if (msg.type === "assistant") {
385→    setAgentStatus(agentId, "thinking");
386→  } else if (msg.type === "result") {
387→    // CLI stays alive after result — ready for the next turn.
388→    // Status only goes to "disconnected" when the CLI WebSocket actually closes.
389→    setAgentStatus(agentId, "connected");
390→  }
391→
392→  // Store control_request inputs for building proper responses later
393→  if (msg.type === "control_request") {
394→    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
395→    if (cr.request_id && cr.request?.input) {
396→      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
397→    }
398→  }
399→
400→  // Record in history and relay to browsers
401→  recordAndSend(agentId, { type: "relay", agentId, message: msg });
402→}
403→
404→/**
405→ * Process an incoming JSON message from the browser.
406→ * - `spawn`: create a new agent (does NOT kill others).
407→ * - `send_message`: forward a follow-up user message to the specified agent.
408→ * - `control_response`: forward a tool allow/deny decision to the specified agent.
409→ */
410→function handleBrowserMessage(raw: string) {
411→  let msg: BrowserMessage;
412→  try {
413→    msg = JSON.parse(raw);
414→  } catch {
415→    console.error("[browser] invalid JSON:", raw);
416→    return;
417→  }
418→
419→  console.log("[browser →]", msg.type);
420→
421→  switch (msg.type) {
422→    case "spawn":
423→      spawnClaude(msg.prompt);
424→      break;
425→
426→    case "send_message": {
427→      const agent = agents.get(msg.agentId);
428→      if (!agent) {
429→        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
430→        break;
431→      }
432→      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
433→        const userMsg = JSON.stringify({
434→          type: "user",
435→          message: { role: "user", content: msg.content },
436→          parent_tool_use_id: null,
437→          session_id: agent.sessionId ?? "",
438→        });
439→        agent.claudeSocket.send(userMsg + "\n");
440→        setAgentStatus(msg.agentId, "thinking");
441→      } else {
442→        // Queue message for delivery when CLI reconnects
443→        const userMsg = JSON.stringify({
444→          type: "user",
445→          message: { role: "user", content: msg.content },
446→          parent_tool_use_id: null,
447→          session_id: agent.sessionId ?? "",
448→        });
449→        agent.pendingMessages.push(userMsg);
450→        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
451→        persistAgentSync(agent);
452→      }
453→      break;
454→    }
455→
456→    case "control_response": {
457→      const agent = agents.get(msg.agentId);
458→      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
459→        // Retrieve the original tool input to include as updatedInput (required by protocol)
460→        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
461→        agent.pendingControlRequests.delete(msg.request_id);
462→
463→        const response = JSON.stringify({
464→          type: "control_response",
465→          response: {
466→            subtype: "success",
467→            request_id: msg.request_id,
468→            response: msg.allow
469→              ? { behavior: "allow", updatedInput: originalInput }
470→              : { behavior: "deny", message: "Denied by user" },
471→          },
472→        });
473→        agent.claudeSocket.send(response + "\n");
474→      }
475→      break;
476→    }
477→  }
478→}
479→
480→// ── Send message history to a single browser socket ────────────────────────
481→
482→/** Send full state to a newly connected browser: agent list + message history per agent. */
483→function sendFullStateToSocket(ws: WebSocket) {
484→  if (ws.readyState !== WebSocket.OPEN) return;
485→
486→  // 1. Agent list
487→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList() }));
488→
489→  // 2. Message history per agent
490→  for (const agent of agents.values()) {
491→    if (agent.messageHistory.length > 0) {
492→      ws.send(
493→        JSON.stringify({
494→          type: "message_history",
495→          agentId: agent.agentId,
496→          messages: agent.messageHistory,
497→        })
498→      );
499→    }
500→  }
501→}
502→
503→// ── Connection handler — route by URL path ────────────────────────────────
504→wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
505→  const path = req.url ?? "/";
506→  console.log(`[ws connected] path=${path}`);
507→
508→  if (path === "/browser") {
509→    browserSockets.add(ws);
510→
511→    // Send full state to this browser
512→    sendFullStateToSocket(ws);
513→
514→    // Attempt to relaunch any disconnected agents
515→    for (const agent of agents.values()) {
516→      if (agent.status === "disconnected" && !agent.claudeSocket) {
517→        relaunchAgent(agent);
518→      }
519→    }
520→
