 96→}
 97→
 98→/** Discriminated union of all known Claude NDJSON message shapes. */
 99→export type ClaudeMessage =
100→  | ClaudeSystemInit
101→  | ClaudeAssistant
102→  | ClaudeResult
103→  | ClaudeControlRequest
104→  | ClaudeSystemHook
