tool_use_result.originalFile:
/**
 * Shared type definitions for the thos dashboard.
 *
 * Three categories:
 * 1. **Claude NDJSON protocol** — messages the Claude CLI sends over its
 *    `--sdk-url` WebSocket connection (CLI → WS server).
 * 2. **Browser ↔ Server** — messages exchanged between the React client
 *    and the standalone WS relay server.
 * 3. **UI state** — view-model types consumed by React components.
 */

// ── Claude NDJSON protocol messages (CLI → server) ────────────────────────

/**
 * Sent once after the first user prompt is received. Contains session
 * metadata like the model name, working directory, and available tools.
 */
export interface ClaudeSystemInit {
  type: "system";
  subtype: "init";
  session_id: string;
  tools: unknown[];
  mcp_servers: unknown[];
  model: string;
  cwd: string;
}

/**
 * An assistant turn. `message.content` is an array of content blocks
 * (text, tool_use, tool_result) that may arrive incrementally — each
 * NDJSON line is a complete snapshot of the message so far.
 */
export interface ClaudeAssistant {
  type: "assistant";
  message: {
    id: string;
    role: "assistant";
    content: AssistantContentBlock[];
    model: string;
    stop_reason: string | null;
  };
  session_id: string;
}

/** A single content block inside an assistant message. */
export type AssistantContentBlock =
  | { type: "text"; text: string }
  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
  | { type: "tool_result"; tool_use_id: string; content: string };

/**
 * Terminal message for a session. Includes cost/duration metrics.
 * `is_error` is true when `subtype` is `"error"`.
 */
export interface ClaudeResult {
  type: "result";
  subtype: "success" | "error";
  result?: string;
  error?: string;
  session_id: string;
  cost_usd: number;
  duration_ms: number;
  duration_api_ms: number;
  is_error: boolean;
  num_turns: number;
}

/**
 * Claude is requesting permission to execute a tool. The dashboard must
 * reply with a `control_response` (allow / deny) before the CLI proceeds.
 *
 * Wire format uses a nested `request` object with `request_id` at the
 * top level for correlation (matches Companion protocol docs).
 */
export interface ClaudeControlRequest {
  type: "control_request";
  request_id: string;
  request: {
    subtype: "can_use_tool";
    tool_name: string;
    input: Record<string, unknown>;
    tool_use_id?: string;
    description?: string;
  };
  session_id?: string;
}

/**
 * Hook lifecycle events emitted during CLI startup. `hook_response` is
 * the signal that the CLI is ready to receive the first user prompt.
 */
export interface ClaudeSystemHook {
  type: "system";
  subtype: "hook_started" | "hook_response";
  session_id?: string;
}

/** Discriminated union of all known Claude NDJSON message shapes. */
export type ClaudeMessage =
  | ClaudeSystemInit
  | ClaudeAssistant
  | ClaudeResult
  | ClaudeControlRequest
  | ClaudeSystemHook
  | { type: string; subtype?: string; [key: string]: unknown };

// ── Browser ↔ Server messages ─────────────────────────────────────────────

/** Browser asks the server to spawn a new Claude CLI process. */
export interface BrowserSpawn {
  type: "spawn";
  prompt: string;
}

/** Browser sends a follow-up message to an already-running Claude session. */
export interface BrowserSendMessage {
  type: "send_message";
  agentId: string;
  content: string;
}

/** Browser responds to a tool approval request (allow or deny). */
export interface BrowserControlResponse {
  type: "control_response";
  agentId: string;
  request_id: string;
  allow: boolean;
}

/** Union of all messages the browser can send to the WS server. */
export type BrowserMessage = BrowserSpawn | BrowserSendMessage | BrowserControlResponse;

/** Server relays a raw Claude NDJSON message to the browser. */
export interface ServerRelay {
  type: "relay";
  agentId: string;
  message: ClaudeMessage;
}

/** Server notifies the browser of an agent status change. */
export interface ServerStatus {
  type: "status";
  agentId: string;
  status: AgentStatus;
}

/** Server reports an error (e.g. no active session, process crash). */
export interface ServerError {
  type: "error";
  agentId: string;
  error: string;
}

/** Summary of an agent for the sidebar. */
export interface AgentInfo {
  agentId: string;
  status: AgentStatus;
  tmuxSession: string | null;
  label: string;
  createdAt: number;
}

/** Server sends the full list of agents after every state change. */
export interface ServerAgentList {
  type: "agent_list";
  agents: AgentInfo[];
}

/** Server confirms a new agent was spawned and assigns its ID. */
export interface ServerSpawned {
  type: "spawned";
  agentId: string;
}

/** Server replays full message history for an agent on browser connect. */
export interface ServerMessageHistory {
  type: "message_history";
  agentId: string;
  messages: ServerMessage[];
}

/** CLI WebSocket disconnected (process may have crashed or exited). */
export interface ServerCliDisconnected {
  type: "cli_disconnected";
  agentId: string;
}

/** CLI WebSocket reconnected (e.g. after relaunch with --resume). */
export interface ServerCliConnected {
  type: "cli_connected";
  agentId: string;
}

/** Union of all messages the WS server can send to the browser. */
export type ServerMessage =
  | ServerRelay
  | ServerStatus
  | ServerError
  | ServerAgentList
  | ServerSpawned
  | ServerMessageHistory
  | ServerCliDisconnected
  | ServerCliConnected;

// ── UI state ──────────────────────────────────────────────────────────────

/**
 * Lifecycle states of the Claude agent process:
 * - `idle`      — no process running, ready to spawn
 * - `spawning`  — process launched, waiting for CLI to connect via WS
 * - `connected` — CLI connected and `system/init` received
 * - `thinking`  — waiting for assistant response
 * - `done`      — `result` message received, process finished
 * - `error`     — process crashed or unexpected failure
 */
export type AgentStatus = "idle" | "spawning" | "connected" | "thinking" | "done" | "disconnected" | "error";

export type ChatMessageRole = "user" | "assistant" | "system";

/**
 * A single entry in the chat message list. System messages include
 * session init info and result summaries. Messages with a `controlRequest`
 * are rendered as tool-approval cards instead of plain bubbles.
 */
export interface ChatMessage {
  id: string;
  role: ChatMessageRole;
  content: string;
  timestamp: number;
  /** Present when this message represents a tool approval request. */
  controlRequest?: {
    id: string;
    tool_name: string;
    input: Record<string, unknown>;
    /** Set to true after the user allows or denies. */
    resolved?: boolean;
  };
}

"use client";

/**
 * React hook that manages the WebSocket connection to the thos relay server.
 *
 * Supports multiple concurrent agents. Each agent has its own status,
 * message history, label, and tmux session name tracked in a Map keyed
 * by agent ID. The `activeAgentId` determines which agent's chat is shown.
 *
 * Resilience features:
 * - Handles `message_history` replay from server on connect/reconnect.
 * - Handles `cli_disconnected` / `cli_connected` events.
 * - Deduplicates messages using a per-agent Set of seen message IDs.
 * - Robust reconnection guard (clears previous timer before scheduling).
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type {
  AgentInfo,
  AgentStatus,
  ChatMessage,
  ClaudeAssistant,
  ClaudeControlRequest,
  ClaudeResult,
  ClaudeSystemInit,
  ServerMessage,
  ServerMessageHistory,
} from "@/lib/types";

const WS_URL = "ws://localhost:9900/browser";

/** Per-agent client state. */
export interface AgentClientState {
  status: AgentStatus;
  messages: ChatMessage[];
  label: string;
  tmuxSession: string | null;
  createdAt: number;
}

/**
 * Extract displayable text from a Claude assistant message.
 * Content blocks may be text, tool_use, or tool_result — each is
 * handled defensively since the array structure can vary.
 */
function extractText(msg: ClaudeAssistant): string {
  const blocks = msg.message?.content;
  if (!blocks || !Array.isArray(blocks)) return "";
  return blocks
    .map((b) => {
      if (b.type === "text") return b.text;
      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
      if (b.type === "tool_result") return `[tool_result: ${b.content}]`;
      return "";
    })
    .filter(Boolean)
    .join("\n");
}

/** Module-level counter for generating unique message IDs. */
let msgCounter = 0;
function nextId() {
  return `msg-${Date.now()}-${++msgCounter}`;
}

/**
 * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
 * Used both for live messages and for replaying message_history.
 */
function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
  if (relayMsg.type === "relay") {
    const msg = relayMsg.message;

    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
      const init = msg as ClaudeSystemInit;
      return {
        id: nextId(),
        role: "system",
        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
        timestamp: Date.now(),
      };
    }

    if (msg.type === "assistant") {
      const text = extractText(msg as ClaudeAssistant);
      if (text) {
        return {
          id: nextId(),
          role: "assistant",
          content: text,
          timestamp: Date.now(),
        };
      }
      return null;
    }

    if (msg.type === "result") {
      const result = msg as ClaudeResult;
      const summary = result.is_error
        ? `Error: ${result.error}`
        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
      return {
        id: nextId(),
        role: "system",
        content: summary,
        timestamp: Date.now(),
      };
    }

    if (msg.type === "control_request") {
      const cr = msg as ClaudeControlRequest;
      return {
        id: nextId(),
        role: "system",
        content: `Tool approval requested: ${cr.request.tool_name}`,
        timestamp: Date.now(),
        controlRequest: {
          id: cr.request_id,
          tool_name: cr.request.tool_name,
          input: cr.request.input,
        },
      };
    }
  }

  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
    return {
      id: nextId(),
      role: "system",
      content: `Error: ${relayMsg.error}`,
      timestamp: Date.now(),
    };
  }

  return null;
}

export function useWebSocket() {
  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [connected, setConnected] = useState(false);

  // Multi-agent state
  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
  const [agentOrder, setAgentOrder] = useState<string[]>([]);
  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);

  // Per-agent deduplication: track count of processed messages per agent
  // to avoid duplicating messages already in local state during history replay.
  const processedCountRef = useRef<Map<string, number>>(new Map());

  /** Immutably update a single agent's state in the Map. */
  const updateAgent = useCallback(
    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
      setAgents((prev) => {
        const existing = prev.get(agentId);
        if (!existing) return prev;
        const next = new Map(prev);
        next.set(agentId, updater(existing));
        return next;
      });
    },
    []
  );

  const connect = useCallback(() => {
    if (wsRef.current?.readyState === WebSocket.OPEN) return;
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }

    const ws = new WebSocket(WS_URL);
    wsRef.current = ws;

    ws.onopen = () => setConnected(true);

    ws.onclose = () => {
      setConnected(false);
      wsRef.current = null;
      // Reconnection guard: clear any existing timer before scheduling
      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
      reconnectTimer.current = setTimeout(() => connect(), 2000);
    };

    ws.onerror = () => {
      // onclose will fire after onerror, which triggers reconnect
    };

    ws.onmessage = (event) => {
      let data: ServerMessage;
      try {
        data = JSON.parse(event.data as string);
      } catch {
        return;
      }

      // ── message_history: replay full history from server ──
      if (data.type === "message_history") {
        const historyMsg = data as ServerMessageHistory;
        const agentId = historyMsg.agentId;
        const serverMessages = historyMsg.messages;

        // Convert all server messages to ChatMessages
        const chatMessages: ChatMessage[] = [];
        for (const sm of serverMessages) {
          const cm = relayChatMessage(agentId, sm);
          if (cm) chatMessages.push(cm);
        }

        // Skip messages already processed locally (dedup)
        const alreadyProcessed = processedCountRef.current.get(agentId) ?? 0;
        const newMessages = chatMessages.slice(alreadyProcessed);

        if (newMessages.length > 0) {
          setAgents((prev) => {
            const existing = prev.get(agentId);
            if (!existing) {
              // Agent not yet in local state — create it
              const next = new Map(prev);
              next.set(agentId, {
                status: "idle",
                messages: chatMessages, // use full history for new agent
                label: "",
                tmuxSession: null,
                createdAt: 0,
              });
              return next;
            }
            // Replace messages with full server history (source of truth)
            const next = new Map(prev);
            next.set(agentId, { ...existing, messages: chatMessages });
            return next;
          });
        }

        processedCountRef.current.set(agentId, chatMessages.length);
        return;
      }

      // ── cli_disconnected: show system message ──
      if (data.type === "cli_disconnected") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          status: "disconnected",
          messages: [
            ...prev.messages,
            {
              id: nextId(),
              role: "system",
              content: "CLI disconnected — attempting reconnect...",
              timestamp: Date.now(),
            },
          ],
        }));
        return;
      }

      // ── cli_connected: show system message ──
      if (data.type === "cli_connected") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [
            ...prev.messages,
            {
              id: nextId(),
              role: "system",
              content: "CLI reconnected",
              timestamp: Date.now(),
            },
          ],
        }));
        return;
      }

      // ── agent_list: reconcile sidebar state from server ──
      if (data.type === "agent_list") {
        const serverAgents = data.agents as AgentInfo[];
        setAgents((prev) => {
          const next = new Map(prev);
          const serverIds = new Set(serverAgents.map((a) => a.agentId));

          // Update or add agents from server
          for (const info of serverAgents) {
            const existing = next.get(info.agentId);
            if (existing) {
              next.set(info.agentId, {
                ...existing,
                status: info.status,
                tmuxSession: info.tmuxSession,
                label: info.label,
              });
            } else {
              next.set(info.agentId, {
                status: info.status,
                messages: [],
                label: info.label,
                tmuxSession: info.tmuxSession,
                createdAt: info.createdAt,
              });
            }
          }

          // Remove agents no longer on the server
          for (const id of next.keys()) {
            if (!serverIds.has(id)) {
              next.delete(id);
            }
          }

          return next;
        });
        setAgentOrder(serverAgents.map((a) => a.agentId));
        return;
      }

      // ── spawned: auto-select the newly created agent ──
      if (data.type === "spawned") {
        setActiveAgentId(data.agentId);
        return;
      }

      // ── status: update a specific agent's status ──
      if (data.type === "status") {
        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
        return;
      }

      // ── error: append to agent's message list ──
      if (data.type === "error") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [
            ...prev.messages,
            {
              id: nextId(),
              role: "system",
              content: `Error: ${data.error}`,
              timestamp: Date.now(),
            },
          ],
        }));
        // Track processed count for dedup
        processedCountRef.current.set(
          data.agentId,
          (processedCountRef.current.get(data.agentId) ?? 0) + 1
        );
        return;
      }

      // ── relay: append claude message to agent's history ──
      if (data.type === "relay") {
        const agentId = data.agentId;
        const chatMsg = relayChatMessage(agentId, data);

        if (chatMsg) {
          updateAgent(agentId, (prev) => ({
            ...prev,
            messages: [...prev.messages, chatMsg],
          }));
          // Track processed count for dedup
          processedCountRef.current.set(
            agentId,
            (processedCountRef.current.get(agentId) ?? 0) + 1
          );
        }
        return;
      }
    };
  }, [updateAgent]);

  useEffect(() => {
    connect();
    return () => {
      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
      wsRef.current?.close();
    };
  }, [connect]);

  const send = useCallback((data: object) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify(data));
    }
  }, []);

  const spawnAgent = useCallback(
    (prompt: string) => {
      send({ type: "spawn", prompt });
    },
    [send]
  );

  const sendMessage = useCallback(
    (content: string) => {
      if (!activeAgentId) return;
      // Optimistically add user message to local state
      updateAgent(activeAgentId, (prev) => ({
        ...prev,
        messages: [
          ...prev.messages,
          {
            id: nextId(),
            role: "user",
            content,
            timestamp: Date.now(),
          },
        ],
      }));
      send({ type: "send_message", agentId: activeAgentId, content });
    },
    [send, activeAgentId, updateAgent]
  );

  const respondToControl = useCallback(
    (requestId: string, allow: boolean) => {
      if (!activeAgentId) return;
      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
      updateAgent(activeAgentId, (prev) => ({
        ...prev,
        messages: prev.messages.map((m) =>
          m.controlRequest?.id === requestId
            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
            : m
        ),
      }));
    },
    [send, activeAgentId, updateAgent]
  );

  // Derived values for the active agent
  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
  const activeStatus = useMemo<AgentStatus>(
    () => activeAgent?.status ?? "idle",
    [activeAgent?.status]
  );
  const activeMessages = useMemo<ChatMessage[]>(
    () => activeAgent?.messages ?? [],
    [activeAgent?.messages]
  );

  return {
    connected,
    agents,
    agentOrder,
    activeAgentId,
    setActiveAgentId,
    activeStatus,
    activeMessages,
    spawnAgent,
    sendMessage,
    respondToControl,
  };
}

